function spiralGrid(n: number): number[][] {
  const grid = Array.from({ length: n }, () => new Array(n).fill(0));
  const dr = [0, 1, 0, -1], dc = [1, 0, -1, 0]; // right, down, left, up
  let r = 0, c = 0, d = 0;
  for (let v = 1; v <= n * n; v++) {
    grid[r][c] = v;
    const nr = r + dr[d], nc = c + dc[d];
    if (nr < 0 || nr >= n || nc < 0 || nc >= n || grid[nr][nc] !== 0) d = (d + 1) % 4;
    r += dr[d];
    c += dc[d];
  }
  return grid;
}

