function spiralGrid(n: number): number[][] {
  const grid = Array.from({ length: n }, () => new Array(n).fill(0));
  let top = 0, bottom = n - 1, left = 0, right = n - 1, v = 1;
  while (top <= bottom && left <= right) {
    for (let c = left; c <= right; c++) grid[top][c] = v++;
    top++;
    for (let r = top; r <= bottom; r++) grid[r][right] = v++;
    right--;
    if (top <= bottom) {
      for (let c = right; c >= left; c--) grid[bottom][c] = v++;
      bottom--;
    }
    if (left <= right) {
      for (let r = bottom; r >= top; r--) grid[r][left] = v++;
      left++;
    }
  }
  return grid;
}

