                v += 1
            top += 1
            for r in range(top, bottom + 1):
                grid[r][right] = v
                v += 1
            right -= 1
            if top <= bottom:
                for c in range(right, left - 1, -1):
                    grid[bottom][c] = v
                    v += 1
                bottom -= 1
            if left <= right:
                for r in range(bottom, top - 1, -1):
                    grid[r][left] = v
                    v += 1
                left += 1
        return grid

